-- An xStats 1.0.1 database, as its Schema (steps 1 and 2) and Store wrote it: one server, one
-- player with kills, playtime and a stat 2.0 doesn't define, a day's rise, a folded month, a
-- board, the source of kills, the import's flag and the schema version in the core's meta table.
CREATE TABLE IF NOT EXISTS xstats_meta (name VARCHAR(64) PRIMARY KEY, value VARCHAR(255) NOT NULL)
CREATE TABLE IF NOT EXISTS xstats_servers (id INTEGER PRIMARY KEY, name VARCHAR(64) NOT NULL UNIQUE)
CREATE TABLE IF NOT EXISTS xstats_stats (id INTEGER PRIMARY KEY, name VARCHAR(64) NOT NULL UNIQUE)
CREATE TABLE IF NOT EXISTS xstats_players (id INTEGER PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, name VARCHAR(16), name_lower VARCHAR(16), first_join BIGINT NOT NULL, last_seen BIGINT NOT NULL, hidden SMALLINT NOT NULL, excluded SMALLINT NOT NULL)
CREATE INDEX xstats_players_name ON xstats_players (name_lower)
CREATE TABLE IF NOT EXISTS xstats_totals (player INT NOT NULL, stat INT NOT NULL, server INT NOT NULL, value BIGINT NOT NULL, raw BIGINT NOT NULL, updated BIGINT NOT NULL, PRIMARY KEY (player, stat, server))
CREATE INDEX xstats_totals_stat ON xstats_totals (stat, server, value)
CREATE TABLE IF NOT EXISTS xstats_daily (player INT NOT NULL, stat INT NOT NULL, server INT NOT NULL, day INT NOT NULL, delta BIGINT NOT NULL, PRIMARY KEY (player, stat, server, day))
CREATE INDEX xstats_daily_day ON xstats_daily (day)
CREATE TABLE IF NOT EXISTS xstats_monthly (player INT NOT NULL, stat INT NOT NULL, server INT NOT NULL, month INT NOT NULL, delta BIGINT NOT NULL, PRIMARY KEY (player, stat, server, month))
CREATE TABLE IF NOT EXISTS xstats_boards (id INTEGER PRIMARY KEY, server INT NOT NULL, world VARCHAR(64) NOT NULL, x DOUBLE NOT NULL, y DOUBLE NOT NULL, z DOUBLE NOT NULL, yaw FLOAT NOT NULL, stat VARCHAR(64) NOT NULL, period VARCHAR(16) NOT NULL)
CREATE TABLE IF NOT EXISTS xstats_sources (stat INT NOT NULL, server INT NOT NULL, source VARCHAR(2048) NOT NULL, PRIMARY KEY (stat, server))
